(()=>{const p=document.createElement('div');p.style.cssText='position:fixed;left:0;top:0;font-size:0';document.body.append(p);const out={};for(const line of ['normal','2','10px']){p.innerHTML='<div style="display:inline-block">Alpha</div>';p.style.lineHeight=line;const e=p.firstElementChild,s=getComputedStyle(e),r=e.getBoundingClientRect();out[line]=[s.fontSize,s.lineHeight,r.width,r.height]}p.style.cssText='position:fixed;font-size:0;width:3em;height:4em';out.em=[getComputedStyle(p).width,getComputedStyle(p).height];p.remove();return out})()